MATCH (pa:PatientAnimal)
CALL {
  WITH pa
  MATCH (pa)<-[:FOR_PATIENT]-(pr:Prescription)
  RETURN pr ORDER BY pr.date_prescribed DESC LIMIT 1
}
CALL {
  WITH pa
  MATCH (pa)-[:EXPERIENCED]->(ar:AdverseReaction)
  RETURN ar ORDER BY ar.reported_date DESC LIMIT 1
}
RETURN pa.name AS patient, pr.date_prescribed AS last_prescription, ar.reported_date AS last_reaction
ORDER BY pa.name

MATCH (v:PrescribingVet)-[:PRESCRIBED]->(pr:Prescription)-[:FOR_PATIENT]->(pa:PatientAnimal)-[:EXPERIENCED]->(ar:AdverseReaction)-[:LINKED_TO_MEDICATION]->(m:Medication)
WHERE ar.severity = 'Critical' AND ar.reported_date > pr.date_prescribed + duration({days: 14}
RETURN v.name, pa.name, ar.reaction_type, pa.allergy_notes, m.name
